<?php $pageTitle='Members';require __DIR__.'/config/database.php';require __DIR__.'/includes/header.php';if($_SERVER['REQUEST_METHOD']==='POST'){require_role(['admin','librarian']);$s=$pdo->prepare("INSERT INTO members(member_code,name,member_type,enrollment_no,department,mobile,email,registered_on) VALUES(?,?,?,?,?,?,?,CURDATE())");$s->execute([trim($_POST['member_code']),trim($_POST['name']),$_POST['member_type'],trim($_POST['enrollment_no']),trim($_POST['department']),trim($_POST['mobile']),trim($_POST['email'])]);}$members=$pdo->query("SELECT * FROM members ORDER BY id DESC")->fetchAll();?><h2>Members</h2><form method="post" class="card card-body shadow-sm mb-4"><div class="row g-2"><div class="col-md-2"><input class="form-control" name="member_code" placeholder="Member ID" required></div><div class="col-md-3"><input class="form-control" name="name" placeholder="Name" required></div><div class="col-md-2"><select class="form-select" name="member_type"><option>student</option><option>faculty</option><option>staff</option><option>other</option></select></div><div class="col-md-2"><input class="form-control" name="enrollment_no" placeholder="Enrollment"></div><div class="col-md-3"><input class="form-control" name="department" placeholder="Department"></div><div class="col-md-2"><input class="form-control" name="mobile" placeholder="Mobile"></div><div class="col-md-3"><input class="form-control" name="email" type="email" placeholder="Email"></div><div class="col-md-2"><button class="btn btn-success">Add Member</button></div></div></form><div class="card shadow-sm"><div class="card-body table-responsive"><table class="table"><tr><th>ID</th><th>Name</th><th>Type</th><th>Department</th><th>Mobile</th><th>Status</th></tr><?php foreach($members as $m):?><tr><td><?=h($m['member_code'])?></td><td><?=h($m['name'])?></td><td><?=h($m['member_type'])?></td><td><?=h($m['department']??'')?></td><td><?=h($m['mobile']??'')?></td><td><?=h($m['status'])?></td></tr><?php endforeach;?></table></div></div><?php require __DIR__.'/includes/footer.php';